R=C=19
g=[[0]*C for _ in range(R)]
# centers of 3x3 objects: (row,col,color)
centers=[(3,7,4),(8,14,8),(13,1,7)]
# draw full center row and column for each; intersections between unlike rays are left empty
for r,c,color in centers:
    for j in range(C): g[r][j]=color
    for i in range(R): g[i][c]=color
# Blank every intersection between one horizontal ray and a differently colored vertical ray.
for r,c,color in centers:
    for rr,cc,col in centers:
        if r==rr and c==cc: continue
        # For each center pair: horizontal of first meets vertical of second
        g[r][cc]=0
        g[rr][c]=0
# Restore original 3x3 blocks (also establishes which cells are filled within objects)
for r,c,color in centers:
    for i in range(r-1,r+2):
      for j in range(c-1,c+2): g[i][j]=color
# Restore intersection blanks after blocks (none should be within blocks)
for r,c,color in centers:
    for rr,cc,col in centers:
        if r!=rr or c!=cc:
            g[r][cc]=0; g[rr][c]=0
print('\n'.join(' '.join(map(str,row)) for row in g))
